local config = {
  ui_story_31880401_1_dialog_content = "<color=#e8d9bb>Um poema diz...</color>",
  ui_story_31880401_2_dialog_content = "<color=#e8d9bb>\"O Rei de Ji, um reino vassalo do Império Zhao, ordenou que a Princesa Zhuohua viajasse como enviada às terras ocidentais.\"</color>",
  ui_story_31880401_3_dialog_content = "<color=#e8d9bb>\"Destemida, ela atravessou montanhas e oceanos, mesmo em meio a conflitos de fronteira, demonstrando coragem inabalável diante das adversidades.\"</color>",
  ui_story_31880401_4_dialog_content = "<color=#e8d9bb>\"Enquanto ela vagava por um vasto deserto, a solidão e o desespero cresciam em seu coração. Sob um céu frio e límpido, suas emoções se tornaram complicadas e intensas.\"</color>",
  ui_story_31880401_5_dialog_content = "<color=#e8d9bb>\"Para aumentar suas aflições, um bando de gansos gritou na direção de Twin Pavilions Bay, e ela foi dominada pela solidão e saudade de casa.\"</color>",
  ui_story_31880401_6_dialog_content = "<color=#e8d9bb>Apesar de suas inúmeras provações e tribulações, a Princesa Zhuohua finalmente chegou às terras ocidentais e, assim, fez uma breve pausa em Twin Pavilions Bay.</color>",
  ui_story_31880401_7_dialog_content = "<color=#e8d9bb>Como o nome sugere, Twin Pavilions Bay é uma cidade dividida em duas, com uma metade governada por Umbraton e a outra pela Lin Guild.</color>",
  ui_story_31880401_8_dialog_content = "<color=#e8d9bb>Na metade da cidade pertencente à Guilda Lin, as ruas e edifícios não são diferentes daqueles da grande cidade do Zhao Império. Isso confunde as pessoas às vezes, sem saber onde estão.</color>",
  ui_story_31880401_9_dialog_content = "<color=#e8d9bb>Dragão Cavalo Bai, Jiu Wukong, Meow Bajie e Zen Wujing olhavam com admiração a metade da cidade de Umbraton, com seus corações cheios de ambição.</color>",
  ui_story_31880401_10_dialog_content = "<color=#e8d9bb>Princesa Zhuohua, no entanto, olhava fixamente para um espelho, com a mente aparentemente ocupada por algo preocupante...</color>",
  ui_story_31880401_11_dialog_content = "<color=#e8d9bb>O belo rosto refletido no espelho traz à mente mais um poema...</color>",
  ui_story_31880401_12_dialog_content = "<color=#e8d9bb>\"Pele tão branca quanto gelo e traços tão finos quanto jade esculpida. Suas bochechas rosadas e lábios vermelhos vivos enchem este mundo de cor e beleza.\"</color>",
  ui_story_31880401_13_dialog_content = "<color=#e8d9bb>\"Ela caminha suavemente, tão leve e elegante quanto uma brisa entre os galhos de um salgueiro. Seus olhos lembram a ternura das pétalas de flores caindo delicadamente sobre um lago.\"</color>",
  ui_story_31880401_14_dialog_content = "Wukong, quanto tempo faz desde que enviamos uma carta ao Rei Leão de Obsidiana solicitando uma audiência?",
  ui_story_31880401_15_dialog_content = "Quinze dias, se incluirmos hoje.",
  ui_story_31880401_16_dialog_content = "O Rei Leão de Obsidiana parece estar ocupado demais para nos responder.",
  ui_story_31880401_17_dialog_content = "Não é bom! Não é bom!",
  ui_story_31880401_18_dialog_content = "Por que está em pânico, Bajie?",
  ui_story_31880401_19_dialog_content = "Fui verificar a casa do Rei Leão de Obsidiana e encontrei nossa carta no lixo! Eles jogaram fora!",
  ui_story_31880401_20_dialog_content = "O quê?",
  ui_story_31880401_21_dialog_content = "Wujing também viu! Pergunte a ele se você não acredita em mim!",
  ui_story_31880401_22_dialog_content = "Ele está dizendo a verdade, Sua Alteza. Eu também vi.",
  ui_story_31880401_23_dialog_content = "... Não é de se admirar que ainda não tenhamos recebido uma resposta.",
  ui_story_31880401_24_dialog_content = "Parece que mal somos dignos da atenção do Rei Leão de Obsidiana.",
  ui_story_31880401_25_dialog_content = "Umbraton não é o único lugar aqui em Astra. Se continuarmos viajando para oeste, podemos visitar Illumina ou até mesmo Eraveil.",
  ui_story_31880401_26_dialog_content = "Concordo! Se eles não nos derem atenção, então nós também não devemos dar!",
  ui_story_31880401_27_dialog_content = "Este Rei Leão nem parece um rei de qualquer maneira. Até onde eu sei, ele é apenas mais um leão sem cérebro!",
  ui_story_31880401_28_dialog_content = "O que você diz, Sua Alteza? Devo ir e dar-lhes uma lição?",
  ui_story_31880401_29_dialog_content = "Absolutamente não.",
  ui_story_31880401_30_dialog_content = "Não estamos aqui para causar problemas. Lembre-se de manter nosso objetivo final em mente.",
  ui_story_31880401_31_dialog_content = "É sempre \"objetivo final\" isso e \"objetivo final\" aquilo. Como vou manter isso em mente se nem posso sair, além de verificar aquele leão?",
  ui_story_31880401_32_dialog_content = "Já chega, Bajie.",
  ui_story_31880401_33_dialog_content = "Nos últimos dias, eu estava preocupado que perderíamos nossa chance de encontrar o Rei Leão Obsidiano se ficássemos vagando demais.",
  ui_story_31880401_34_dialog_content = "Mas parece que não precisamos mais nos preocupar com isso.",
  ui_story_31880401_35_dialog_content = "Aqui, Wukong. Pegue a prata, junto com Bajie e Wujing, e divirtam-se.",
  ui_story_31880401_36_dialog_content = "Mas e você, Sua Alteza?",
  ui_story_31880401_37_dialog_content = "Acho que vou ficar aqui e descansar um pouco. Vocês três vão em frente.",
  ui_story_31880401_38_dialog_content = "Descanse bastante então, Alteza! Nós traremos algumas frutas cristalizadas para você mais tarde!",
  ui_story_31880401_39_dialog_content = "Sua Alteza! Já está acordado?",
  ui_story_31880401_40_dialog_content = "Essas frutas cristalizadas têm o mesmo sabor das que comíamos em casa! Aqui, experimente algumas!",
  ui_story_31880401_41_dialog_content = "Hã? O-Onde está Sua Alteza?!",
  ui_story_31880401_42_dialog_content = "Ela não nos deixou para trás para se divertir sozinha, deixou?!",
  ui_story_31880401_43_dialog_content = "Não, o xale dela ainda está aqui, o que significa que Sua Alteza provavelmente não saiu por vontade própria. Se é que...",
  ui_story_31880401_44_dialog_content = "Se alguma coisa...?",
  ui_story_31880401_45_dialog_content = "Parece um sequestro.",
  ui_story_31880401_46_dialog_content = "O quê?!",
  ui_story_31880401_47_dialog_content = "Mas nós não incomodamos ninguém aqui! Por que eles sequestrariam Sua Alteza?",
  ui_story_31880401_48_dialog_content = "Além de nós, há apenas uma pessoa que sabe que Sua Alteza está aqui agora mesmo.",
  ui_story_31880401_49_dialog_content = "O Rei Leão de Obsidiana?",
  ui_story_31880401_50_dialog_content = "Vou me transformar em um inseto e investigar. Vocês dois fiquem aqui e mantenham a discrição.",
  ui_story_31880401_51_dialog_content = "<color=#e8d9bb>Puf!</color>",
  ui_story_31880401_52_dialog_content = "Quem diria que esse cara tinha um quarto escondido assim em sua casa?",
  ui_story_31880401_53_dialog_content = "Hmm? Tem alguém à frente!",
  ui_story_31880401_54_dialog_content = "Solte-me!",
  ui_story_31880401_55_dialog_content = "Hahaha! Não acha que suas lutas são praticamente em vão agora?",
  ui_story_31880401_56_dialog_content = "Você... O que exatamente está planejando?",
  ui_story_31880401_57_dialog_content = "Eu poderia te fazer a mesma pergunta. Me diga, por que você veio para Astra?",
  ui_story_31880401_58_dialog_content = "Deixei bem claro na carta. Estamos aqui em uma missão de intercâmbio cultural...",
  ui_story_31880401_59_dialog_content = "Um \"intercâmbio cultural\"? Que maneira agradável de expressar isso.",
  ui_story_31880401_60_dialog_content = "Você pode dispensar o teatro agora. Sabemos que você está trabalhando como espião para o leste.",
  ui_story_31880401_61_dialog_content = "Embora você afirme buscar uma troca cultural, o que você realmente deseja são os segredos mais bem guardados de Astra.",
  ui_story_31880401_62_dialog_content = "Você está errado!",
  ui_story_31880401_63_dialog_content = "Então me diga, o que aconteceria se conseguíssemos firmar um acordo comercial com sucesso?",
  ui_story_31880401_64_dialog_content = "Tanto o leste quanto o oeste se beneficiariam muito com isso. A maquinaria ocidental apareceria no leste e a engenhosidade oriental viria para cá.",
  ui_story_31880401_65_dialog_content = "Como você está muito errado.",
  ui_story_31880401_66_dialog_content = "Quando chegar a hora, seu povo reduzirá os preços de seus produtos e inundará todo o Astra com eles.",
  ui_story_31880401_67_dialog_content = "Uma vez que nossos mercados internos estejam debilitados e nosso povo não tenha como ganhar a vida...",
  ui_story_31880401_68_dialog_content = "Seu imperador enviará suas forças para atacar e conquistar todo o Astra!",
  ui_story_31880401_69_dialog_content = "Isso é absurdo!",
  ui_story_31880401_70_dialog_content = "Não viajei milhares de quilômetros até Astra apenas para criar ainda mais conflitos entre nossas culturas...",
  ui_story_31880401_71_dialog_content = "Oh? Ainda negando isso?",
  ui_story_31880401_72_dialog_content = "Então, deixe-me fazer uma última pergunta.",
  ui_story_31880401_73_dialog_content = "Minhas fontes me dizem que quem conseguir obter o poder em seu corpo pode se tornar o Aurorian mais poderoso da existência. Isso é verdade?",
  ui_story_31880401_74_dialog_content = "O... O que você está planejando fazer comigo?!",
  ui_story_31880401_75_dialog_content = "Oh, olhe para você, parece ser verdade.",
  ui_story_31880401_76_dialog_content = "...!!!",
  ui_story_31880401_77_dialog_content = "Zumbido, zumbido, zumbido!",
  ui_story_31880401_78_dialog_content = "De onde veio esse inseto?",
  ui_story_31880401_79_dialog_content = "<color=#e8d9bb>Bata!</color>",
  ui_story_31880401_80_dialog_content = "O que você disse?!",
  ui_story_31880401_81_dialog_content = "Então aquele monstro quer roubar o poder de Sua Alteza?",
  ui_story_31880401_82_dialog_content = "Por que não pensei nessa possibilidade...?",
  ui_story_31880401_83_dialog_content = "Ei, espere um minuto. Com Sua Alteza ausente, isso não significa que eu posso ir aonde eu quiser?",
  ui_story_31880401_84_dialog_content = "...",
  ui_story_31880401_85_dialog_content = "Ei, ei! Sua Alteza disse que você não pode me bater!",
  ui_story_31880401_86_dialog_content = "Eu não ia. Agora ouça com atenção, cada um de nós tem um trabalho a fazer agora...",
  ui_story_31880401_87_dialog_content = "Saia, monstro leão! Eu sei que você está aí!",
  ui_story_31880401_88_dialog_content = "Se você tem coragem de sequestrar nossa princesa, também deveria ter coragem de admitir isso!",
  ui_story_31880401_89_dialog_content = "Como você ousa latir na minha porta como um cão vadio?",
  ui_story_31880401_90_dialog_content = "E-Ele saiu... Agora depende de você, Wujing!",
  ui_story_31880401_91_dialog_content = "Sim, sim, eu sei.",
  ui_story_31880401_92_dialog_content = "Prepare-se, Rei Leão de Obsidiana! Agora que você sequestrou nossa princesa, não tenho motivos para me conter!",
  ui_story_31880401_93_dialog_content = "Toma essa!",
  ui_story_31880401_94_dialog_content = "Hunf, truques tão mesquinhos.",
  ui_story_31880401_95_dialog_content = "Ugh...",
  ui_story_31880401_96_dialog_content = "E-Ele é muito forte! Devemos apenas correr—",
  ui_story_31880401_97_dialog_content = "Saindo tão cedo? Esqueceu onde está agora?",
  ui_story_31880401_98_dialog_content = "Você não vai escapar tão facilmente!",
  ui_story_31880401_99_dialog_content = "...",
  ui_story_31880401_100_dialog_content = "Espere, eles estão... tentando me atrair para longe?",
  ui_story_31880401_101_dialog_content = "Urgh... O que...",
  ui_story_31880401_102_dialog_content = "Hmph, não se preocupe em procurar. A princesa está segura e bem agora.",
  ui_story_31880401_103_dialog_content = "Agora podemos realmente nos divertir.",
  ui_story_31880401_104_dialog_content = "Toma essa!",
  ui_story_31880401_105_dialog_content = "Espere!",
  ui_story_31880401_106_dialog_content = "Cavalo Dragão Bai? Você não deveria estar cuidando do nosso equipamento?",
  ui_story_31880401_107_dialog_content = "Encontrei a filha do Rei Leão Obsidiana - a Fada do Sino.",
  ui_story_31880401_108_dialog_content = "Todos, por favor, abaixem suas armas.",
  ui_story_31880401_109_dialog_content = "Mestre...",
  ui_story_31880401_110_dialog_content = "\"Mestre\"? Isso é novo. Por que seu pai te chamaria assim?",
  ui_story_31880401_111_dialog_content = "Veja por si mesmo.",
  ui_story_31880401_112_dialog_content = "<color=#e8d9bb>Puf!</color>",
  ui_story_31880401_113_dialog_content = "...",
  ui_story_31880401_114_dialog_content = "O que é isso...?",
  ui_story_31880401_115_dialog_content = "Este é o Frankel, meu espectro.",
  ui_story_31880401_116_dialog_content = "Parece que Frankel assumiu a aparência do meu pai enquanto estávamos fora e causou a você não poucos problemas.",
  ui_story_31880401_117_dialog_content = "Ah? Então quem me chamou de cão vadio foi nada menos que o animal de estimação da família, né?",
  ui_story_31880401_118_dialog_content = "Tadinha...",
  ui_story_31880401_119_dialog_content = "Cuide da sua língua, Bajie.",
  ui_story_31880401_120_dialog_content = "Hmph! Como você ainda pode ser tão cortês com eles, Sua Alteza? Já se esqueceu do que aconteceu com você?",
  ui_story_31880401_121_dialog_content = "Foi minha culpa por não treinar o Frankel bem o suficiente.",
  ui_story_31880401_122_dialog_content = "Por favor, aceite minhas mais sinceras desculpas!",
  ui_story_31880401_123_dialog_content = "Vou ficar de olho no Frankel para que isso nunca mais aconteça.",
  ui_story_31880401_124_dialog_content = "Como um pedido de desculpas, permita-me cobrir suas despesas de viagem enquanto você continua sua jornada para o oeste.",
  ui_story_31880401_125_dialog_content = "E se você quiser... Eu também posso acompanhá-la para ver meu pai, princesa.",
  ui_story_31880401_126_dialog_content = "Isso seria muito apreciado.",
  ui_story_31880401_127_dialog_content = "<color=#e8d9bb>Pouco tempo depois, a Princesa Zhuohua finalmente conseguiu uma audiência com o Rei Leão de Obsidiana, o governante de Umbraton.</color>",
  ui_story_31880401_128_dialog_content = "<color=#e8d9bb>Mas ela realmente será capaz de cumprir sua missão de intercâmbio cultural?",
  ui_story_31880401_129_dialog_content = "<color=#e8d9bb>Leia o próximo capítulo para descobrir!</color>",
  ui_story_31880401_130_dialog_content = "Uau, esse livro parece...",
  ui_story_31880401_131_option_content = "Difícil de entender.",
  ui_story_31880401_132_dialog_content = "Os romances do leste realmente precisam ser tão difíceis de ler?",
  ui_story_31880401_133_dialog_content = "Heheh, nós chamamos esses de \"poemas de sete caracteres.\"",
  ui_story_31880401_134_dialog_content = "Os literatos de Zhao gostam de escrever e recitar poemas como este para expressar seus sentimentos.",
  ui_story_31880401_135_dialog_content = "Não é incomum vê-los em nossos romances também.",
  ui_story_31880401_136_option_content = "Realmente interessante!",
  ui_story_31880401_137_dialog_content = "Acho que nunca li um romance tão imaginativo...",
  ui_story_31880401_138_dialog_content = "Parece que conheço esses personagens na vida real, mas eles parecem muito mais sofisticados na história.",
  ui_story_31880401_139_dialog_content = "Você estava certo, esse romance é realmente interessante!",
  ui_story_31880401_140_dialog_content = "Parece que compartilhar este romance com você foi a escolha certa, afinal.",
  ui_story_31880401_141_dialog_content = "O autor também trabalha muito rápido!",
  ui_story_31880401_142_dialog_content = "Vocês não estão no Astra há muito tempo, mas sua história já está sendo publicada por toda a nossa terra!",
  ui_story_31880401_143_dialog_content = "Hmph, parece ser outro romance barato para mim.",
  ui_story_31880401_144_dialog_content = "Acontece que sou um médico famoso e respeitado que ajuda os feridos e os que sofrem.",
  ui_story_31880401_145_dialog_content = "Mas essa história me faz parecer um gato chorão e preguiçoso!",
  ui_story_31880401_146_dialog_content = "Que monte de besteira!",
  ui_story_31880401_147_dialog_content = "Ah, não veja dessa forma.",
  ui_story_31880401_148_dialog_content = "Ao viajar pelo mundo como nós, ter outra identidade é o mesmo que ter outra camada de proteção.",
  ui_story_31880401_149_dialog_content = "Acho que esses romances são muito bem escritos.",
  ui_story_31880401_150_dialog_content = "Você tem alguma outra identidade, Tianxian?",
  ui_story_31880401_151_dialog_content = "Agora, por que você perguntaria algo assim? Segredos não são para serem compartilhados, sabe!",
  ui_story_31880401_152_dialog_content = "Espere, volte...",
  ui_story_31880401_153_dialog_content = "Minha investigação está completa, Alteza.",
  ui_story_31880401_154_dialog_content = "A pessoa que publicou esses romances é um homem do Deserto Rediesel chamado Jomu.",
  ui_story_31880401_155_dialog_content = "O autor também não parece ser de Zhao.",
  ui_story_31880401_156_dialog_content = "Esta pessoa Jomu parece estar planejando uma viagem para Zhao a fim de expandir seus interesses comerciais.",
  ui_story_31880401_157_dialog_content = "Precisa que eu me desfaça dele?",
  ui_story_31880401_158_dialog_content = "Oh? Eu sinceramente pensei que esses romances fossem escritos por um de nossos compatriotas.",
  ui_story_31880401_159_dialog_content = "Eu não fazia ideia de que alguém em Astra fosse tão versado no estilo literário de Zhao!",
  ui_story_31880401_160_dialog_content = "Os livros gratuitos que você trouxe de Zhou têm circulado bastante por aqui. Acredito que isso possa ter algo a ver com isso.",
  ui_story_31880401_161_dialog_content = "Parece que não há escassez de talento no Astra, então.",
  ui_story_31880401_162_dialog_content = "E Jomu...?",
  ui_story_31880401_163_dialog_content = "Ele se saiu bem, então devemos apoiar seus esforços.",
  ui_story_31880401_164_dialog_content = "Como enviado a Astra, este é exatamente o tipo de intercâmbio cultural que desejo promover.",
  ui_story_31880401_165_dialog_content = "Embora a história desses romances tenha sido bastante enfeitada, isso não deve tirar o seu valor.",
  ui_story_31880401_166_dialog_content = "A expressão de diferentes pontos de vista e ideologias...",
  ui_story_31880401_167_dialog_content = "Esta é parte da prosperidade cultural que busco.",
  ui_story_31880401_168_dialog_content = "Não apenas isso...",
  ui_story_31880401_169_dialog_content = "\"Pele tão branca quanto gelo e traços tão delicados quanto jade esculpida. Suas bochechas rosadas e lábios vermelhos vivos enchem este mundo de cor e beleza.\"",
  ui_story_31880401_170_dialog_content = "\"Ela caminha suavemente, tão leve e elegante quanto uma brisa entre os galhos de um salgueiro. Seus olhos lembram a ternura das pétalas de flores caindo delicadamente sobre um lago de água.\"",
  ui_story_31880401_171_dialog_content = "Por mais bobo que pareça, ainda gosto bastante dessas linhas.",
  ui_story_31880401_172_dialog_content = "Hehehe!",
  ui_story_31880601_1_dialog_content = "O som das ondas sussurrando na noite gentil e o tremular das sombras à luz de velas...",
  ui_story_31880601_2_dialog_content = "Esta noite está linda.",
  ui_story_31880601_3_dialog_content = "Isso é.",
  ui_story_31880601_4_dialog_content = "Desde que deixei minha terra natal pelo Reino de Ji... tive poucas oportunidades para momentos de lazer como este.",
  ui_story_31880601_5_dialog_content = "Muito obrigado por me convidar para admirar a lua da praia.",
  ui_story_31880601_6_dialog_content = "Sua gentil oferta me trouxe muita alegria hoje.",
  ui_story_31880601_7_dialog_content = "Você não precisa ser tão educado! Eu também estou me divertindo...",
  ui_story_31880601_8_dialog_content = "Heheh, parece que a contemplação da lua de hoje foi um grande sucesso para nós dois.",
  ui_story_31880601_9_dialog_content = "Permita-me fazer um brinde a você, meu amigo...",
  ui_story_31880601_10_dialog_content = "Ahh, o som das ondas é realmente reconfortante... Realmente me faz lembrar de uma certa memória do meu passado.",
  ui_story_31880601_11_dialog_content = "Uma memória específica?",
  ui_story_31880601_12_dialog_content = "Sim. Na época, eu tinha acabado de chegar no Reino de Ji e passei muito tempo perto do porto.",
  ui_story_31880601_13_dialog_content = "Minha terra natal, o Reino de Ye, é conhecida por sua habilidade artesanal especializada, bem como seu profundo conhecimento em maquinário...",
  ui_story_31880601_14_dialog_content = "Mas eu nunca tinha encontrado uma terra tão próspera de comércio e competição. Era realmente um espetáculo a ser visto.",
  ui_story_31880601_15_dialog_content = "Foi uma experiência tão reveladora para alguém que acabara de chegar... Naquela época, eu costumava olhar para a distância, perdido em meus próprios pensamentos.",
  ui_story_31880601_16_dialog_content = "Lá no horizonte, onde o céu sem limites encontra o vasto mar, inúmeros navios transportando todos os tipos de maravilhas navegavam para lá e para cá...",
  ui_story_31880601_17_dialog_content = "Uh-huh...",
  ui_story_31880601_18_dialog_content = "Tem algum problema? Ou está ficando tarde demais para você?",
  ui_story_31880601_19_option_content = "Hã? Não... Por favor, continue...",
  ui_story_31880601_20_option_content = "Só estou... um pouco cansado...",
  ui_story_31880601_21_dialog_content = "Heheh, fique à vontade para descansar os olhos um pouco.",
  ui_story_31880601_22_dialog_content = "Bem aqui, do meu lado...",
  ui_story_31880601_23_dialog_content = "...",
  ui_story_31880601_24_dialog_content = "... Hã? Onde estou? Que lugar é esse?",
  ui_story_31880601_25_dialog_content = "Desculpe-me, mas você está bem?",
  ui_story_31880601_26_dialog_content = "D... Dantang?",
  ui_story_31880601_27_dialog_content = "Hum? Não acredito que nos conhecemos antes. Como você sabe meu nome, senhor?",
  ui_story_31880601_28_dialog_content = "Será que... já me tornei conhecido?",
  ui_story_31880601_29_dialog_content = "Uh, como devo explicar isso... Tenho quase certeza de que estou sonhando agora.",
  ui_story_31880601_30_dialog_content = "Heheh, seria bem interessante se tudo isso fosse apenas um sonho.",
  ui_story_31880601_31_dialog_content = "Diga-me, o que um sonhador como você acha deste lugar?",
  ui_story_31880601_32_dialog_content = "Esta é sua primeira vez no porto do Reino Ji, certo?",
  ui_story_31880601_33_dialog_content = "Minha primeira vez em um sonho.",
  ui_story_31880601_34_dialog_content = "Então, parece que você precisa de um guia.",
  ui_story_31880601_35_dialog_content = "A verdade é que eu também não estou nesta cidade há muito tempo.",
  ui_story_31880601_36_dialog_content = "Mas eu sou bastante familiarizado com essa parte da cidade, já que venho aqui com frequência.",
  ui_story_31880601_37_dialog_content = "Você é mais do que bem-vindo para se juntar a mim, se quiser?",
  ui_story_31880601_38_dialog_content = "Em alguns minutos, deveremos ser capazes de ver muitos navios grandes.",
  ui_story_31880601_39_dialog_content = "Navios grandes?",
  ui_story_31880601_40_dialog_content = "Sim, enormes que são tão grandes quanto... Ah, olha, eles estão aqui!",
  ui_story_31880601_41_dialog_content = "Tão grandes quanto casas, e suas enormes velas se enchem como nuvens no céu... É realmente de tirar o fôlego.",
  ui_story_31880601_42_dialog_content = "Rezo para que eu possa embarcar em um desses navios algum dia.",
  ui_story_31880601_43_dialog_content = "Para onde você iria?",
  ui_story_31880601_44_dialog_content = "Onde eu iria? Agora que você mencionou... Eu nunca pensei muito nisso.",
  ui_story_31880601_45_dialog_content = "Os guardas dizem que esses navios enfrentam ondas traiçoeiras e tempestades uivantes para negociar com terras distantes.",
  ui_story_31880601_46_dialog_content = "As pessoas resistentes a bordo desses navios trocam mercadorias por ouro e vice-versa.",
  ui_story_31880601_47_dialog_content = "Viajando constantemente em todas as direções sem um momento de descanso... Ninguém consegue entender o que os motiva a fazer isso.",
  ui_story_31880601_48_dialog_content = "Mas eu invejo eles mesmo assim.",
  ui_story_31880601_49_dialog_content = "Eu não os invejaria tanto assim. Longas viagens como essa podem ser realmente perigosas.",
  ui_story_31880601_50_dialog_content = "As pessoas aqui também concordariam. Os guardas, os trabalhadores do cais e todos os outros.",
  ui_story_31880601_51_dialog_content = "A cada onda de partidas, sempre há navios que nunca retornam.",
  ui_story_31880601_52_dialog_content = "Talvez eles tenham se perdido no mar ou sido atacados por espíritos malignos do oceano.",
  ui_story_31880601_53_dialog_content = "Há até histórias de homens que se apaixonam pelas filhas do deus do mar, casam-se com elas e perdem toda a esperança de retornar à terra.",
  ui_story_31880601_54_dialog_content = "Sempre que um navio embarca em outra viagem, há sempre conversas sobre destino, perigo e presságios indiscerníveis...",
  ui_story_31880601_55_dialog_content = "Mas, apesar de tudo, ainda desejo embarcar em um desses enormes navios.",
  ui_story_31880601_56_dialog_content = "Mesmo sabendo que é perigoso? Por que você gostaria de fazer isso?",
  ui_story_31880601_57_dialog_content = "Porque, além de sua carga, esses navios também carregam tantas esperanças e sonhos das pessoas...",
  ui_story_31880601_58_dialog_content = "E eu desejo ver por mim mesmo os lugares onde essas esperanças e sonhos se realizam!",
  ui_story_31880601_59_dialog_content = "Ao fazer isso, posso me tornar alguém capaz de realizar os desejos do povo...",
  ui_story_31880601_60_dialog_content = "Você vê... Como posso explicar...?",
  ui_story_31880601_61_dialog_content = "... Deixa pra lá! Eu soaria como uma garotinha sonhadora...",
  ui_story_31880601_62_dialog_content = "Hahaha, não se preocupe com isso! Tenho certeza que você conseguirá se expressar claramente conforme for crescendo.",
  ui_story_31880601_63_dialog_content = "Não há nada de errado em ter um sonho ou falar sobre ele, aliás.",
  ui_story_31880601_64_dialog_content = "Concordo! Então, quando eu crescer, com certeza vou embarcar em um desses navios!",
  ui_story_31880601_65_dialog_content = "Verei por mim mesma o que existe além e abaixo do mar! E quando esse dia chegar, saberei exatamente como descrever os sentimentos em meu coração.",
  ui_story_31880601_66_dialog_content = "Então estarei te esperando do outro lado do mar.",
  ui_story_31880601_67_dialog_content = "Você promete?",
  ui_story_31880601_68_dialog_content = "Eu prometo.",
  ui_story_31880601_69_dialog_content = "... Você promete...?",
  ui_story_31880601_70_dialog_content = "Eu...?",
  ui_story_31880601_71_dialog_content = "Ah, você está acordado. Mas você não dormiu por muito tempo.",
  ui_story_31880601_72_dialog_content = "Você sonhou com algo?",
  ui_story_31880601_73_dialog_content = "Dantang...?",
  ui_story_31880601_74_dialog_content = "Hmm... Não me lembro muito bem, mas com certeza tive um sonho agora mesmo.",
  ui_story_31880601_75_dialog_content = "Sério? Você também estava falando dormindo, resmungando sobre navios, promessas e coisas assim.",
  ui_story_31880601_76_dialog_content = "May Eu pergunto, com o que você estava sonhando?",
  ui_story_31880601_77_dialog_content = "É meio difícil de explicar... De alguma forma, sinto como se tivesse acontecido há muito tempo atrás...",
  ui_story_31880601_78_dialog_content = "Heheh, você realmente é uma pessoa interessante.",
  ui_story_31880601_79_dialog_content = "Transcendendo o tempo através dos sonhos... A ideia certamente inspira reflexão.",
  ui_story_31880601_80_dialog_content = "Heh, eu prometo que não estou tentando soar confuso ou algo assim. Colocar isso em palavras realmente é um pouco difícil...",
  ui_story_31880601_81_dialog_content = "Por causa de nossas habilidades psíquicas, entrar e interpretar sonhos é bem fácil...",
  ui_story_31880601_82_dialog_content = "Também já usei uma técnica de sonho semelhante para ver o que está no coração das outras pessoas.",
  ui_story_31880601_83_dialog_content = "Isso me ajuda a resolver muitos problemas no mundo real que, caso contrário, eu não teria como solucionar.",
  ui_story_31880601_84_dialog_content = "É por isso que meus próprios sonhos geralmente são uma combinação subconsciente de informações...",
  ui_story_31880601_85_dialog_content = "É como se meu cérebro estivesse trabalhando horas extras durante o sono, juntando pedaços de conhecimento que adquiro durante o dia...",
  ui_story_31880601_86_dialog_content = "Pfft—",
  ui_story_31880601_87_dialog_content = "Oh! Desculpe, eu não disse algo estranho agora, disse...?",
  ui_story_31880601_88_dialog_content = "De jeito nenhum! Afinal, estamos falando de sonhos.",
  ui_story_31880601_89_dialog_content = "Relembrando, eu sonhava bastante durante meus anos de formação no Reino Ji.",
  ui_story_31880601_90_dialog_content = "Às vezes, eu até sonhava em cavalgar em um navio enorme enquanto ele partia para outra viagem...",
  ui_story_31880601_91_dialog_content = "Você ainda sonha em sair para o mar?",
  ui_story_31880601_92_dialog_content = "Com certeza, embora meus sonhos não sejam mais tão misteriosos como antes.",
  ui_story_31880601_93_dialog_content = "Afinal, eu até já andei a bordo do seu Colosso agora.",
  ui_story_31880601_94_dialog_content = "Agora que você mencionou... Se nada disso tivesse acontecido, você ainda gostaria de ir para o mar?",
  ui_story_31880601_95_dialog_content = "Não há como negar que embarcar em uma viagem oceânica é o mesmo que colocar sua vida nas mãos do destino.",
  ui_story_31880601_96_dialog_content = "Mas, ao escolher ir para o mar, não seria o mesmo que tomar o destino em suas próprias mãos também?",
  ui_story_31880601_97_dialog_content = "Mas você ainda pode acabar na barriga de um peixe gigante.",
  ui_story_31880601_98_dialog_content = "Desde o momento em que nasci, meu destino supostamente foi definido em pedra, e o povo do Reino Ye passou a me considerar uma alma amaldiçoada.",
  ui_story_31880601_99_dialog_content = "Mas, em minhas viagens, aprendi que o destino não é tão imutável quanto acreditamos.",
  ui_story_31880601_100_dialog_content = "É por isso que acredito que nós, como pessoas, temos o poder de lutar contra o desconhecido e até mesmo contra os próprios céus.",
  ui_story_31880601_101_dialog_content = "E você? O que você faria?",
  ui_story_31880601_102_dialog_content = "Se você enfrentasse uma oportunidade como essa, também escolheria zarpar?",
  ui_story_31880601_103_option_content = "Eu iria para o mar!",
  ui_story_31880601_104_dialog_content = "Como esperado, você e eu pensamos da mesma forma.",
  ui_story_31880601_105_option_content = "Tenho meu próprio caminho a seguir!",
  ui_story_31880601_106_dialog_content = "Você tem toda a razão. Afinal, seu destino está em suas próprias mãos.",
  ui_story_31880601_107_dialog_content = "Não há necessidade de seguir os passos dos outros ou fazer o que já foi feito por eles.",
  ui_story_31880601_108_dialog_content = "Você só precisa manter seu próprio destino à vista e assumir o controle firme dele.",
  ui_story_31880601_109_dialog_content = "Dessa forma, seja no mar ou diante de mudanças inesperadas, você nunca perderá seu caminho.",
  ui_story_31880601_110_dialog_content = "E se você se perder, tudo o que precisa fazer é olhar para trás.",
  ui_story_31880601_111_dialog_content = "Sempre haverá alguém te esperando.",
  ui_story_31880601_112_dialog_content = "Eu deveria ter sabido... A resposta que você encontrou depois de crescer...",
  ui_story_31880601_113_dialog_content = "É muito mais incrível do que eu poderia imaginar!",
  ui_story_31880601_114_dialog_content = "Hum? Não entendo...",
  ui_story_31880601_115_dialog_content = "N-Não é nada! Desculpe interromper!",
  ui_story_31880601_116_dialog_content = "Agora, onde estávamos... Ah—eu também estarei sempre esperando atrás de você, Dantang!",
  ui_story_31880601_117_dialog_content = "PlayerName...",
  ui_story_31880601_118_dialog_content = "Eu juro... Então vamos continuar conversando... Eu prometo que... não estou tão cansado assim...",
  ui_story_31880601_119_dialog_content = "Oh? Parece que ficamos acordados até tarde demais. Você também precisa descansar.",
  ui_story_31880601_120_dialog_content = "A lua se escondeu atrás de um véu de nuvens escuras, então vamos encerrar a observação de hoje por enquanto.",
  ui_story_31880601_121_dialog_content = "Permita-me acompanhá-lo de volta ao seu alojamento.",
